import java.io.*;
import java.lang.reflect.Array;
import java.util.*;

public class Main {
    private static int solve(char[] s, char x) {
        for(int i = 0; i < s.length; i++) {
            if(s[i] == 'X') {
                s[i] = x;
            }
        }
        if(s[0] == '0') {
            return 0;
        }
        int ans = 1;
        boolean first = true;
        for(int i = 0; i < s.length; i++) {
            if(s[i] == '_') {
                ans *= i == 0 ? 9 : 10;
            } else if(s[i] == 'X' && first) {
                ans *= i == 0 ? 9 : 10;
                first = false;
            }
        }
        return ans;
    }
    private static boolean canReplace(char[] s, char a, char b) {
        if(s[s.length-2] >= '0' && s[s.length-2] <= '9' && s[s.length-2] != a) {
            return false;
        }
        if(s[s.length-1] >= '0' && s[s.length-1] <= '9' && s[s.length-1] != b) {
            return false;
        }
        if(s[s.length-2] == 'X' && s[s.length-1] == 'X' && a != b) {
            return false;
        }
        return true;
    }
    public static void main(String[] args) throws IOException{
        //BufferedReader f = new BufferedReader(new FileReader("cowjump.in"));
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        //PrintWriter out = new PrintWriter(new BufferedWriter(new FileWriter("cowjump.out")));
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        char[] s = f.readLine().toCharArray();
        if(s.length < 2) {
            out.println(s[0] == '0' || s[0] == '_' || s[0] == 'X' ? 1 : 0);
        } else {
            int ans = 0;
            if(canReplace(s, '0', '0')) {
                char[] t = s.clone();
                t[t.length-2] = '0';
                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    ans += solve(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    ans += solve(t, t[t.length-1]);
                } else {
                    ans += solve(t, 'X');
                }
            }
            if(canReplace(s, '2', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '2';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    ans += solve(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    ans += solve(t, t[t.length-1]);
                } else {
                    ans += solve(t, 'X');
                }
            }
            if(canReplace(s, '5', '0')) {
                char[] t = s.clone();
                t[t.length-2] = '5';
                t[t.length-1] = '0';
                if(s[s.length-2] == 'X') {
                    ans += solve(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    ans += solve(t, t[t.length-1]);
                } else {
                    ans += solve(t, 'X');
                }
            }
            if(canReplace(s, '7', '5')) {
                char[] t = s.clone();
                t[t.length-2] = '7';
                t[t.length-1] = '5';
                if(s[s.length-2] == 'X') {
                    ans += solve(t, t[t.length-2]);
                } else if(s[s.length-1] == 'X') {
                    ans += solve(t, t[t.length-1]);
                } else {
                    ans += solve(t, 'X');
                }
            }
            out.println(ans);
        }
        f.close();
        out.close();
    }
}

